import json

def truncate_contexts(documents: list[dict], max_total_bytes: int, max_document_bytes: int) -> list[dict]:
    if not documents:
        return []

    def apply_limit(limit: int) -> list[dict]:
        res = []
        for doc in documents:
            doc_id = doc.get("document_id")
            chunk_id = doc.get("chunk_id")
            content = doc.get("content", "")

            # UTF-8 byte length of the original content
            orig_bytes = len(content.encode("utf-8"))

            if orig_bytes <= limit:
                truncated_content = content
            else:
                marker = "[truncated]"
                marker_bytes = marker.encode("utf-8")
                if limit < len(marker_bytes):
                    # If the limit is too small even for the marker, just slice to limit bytes
                    truncated_content = content.encode("utf-8")[:limit].decode("utf-8", errors="ignore")
                else:
                    allowed_bytes = limit - len(marker_bytes)
                    prefix_bytes = content.encode("utf-8")[:allowed_bytes]
                    truncated_content = prefix_bytes.decode("utf-8", errors="ignore") + marker

            res.append({
                "document_id": doc_id,
                "chunk_id": chunk_id,
                "content": truncated_content,
                "original_bytes": orig_bytes
            })
        return res

    def get_serialized_size(docs_list: list[dict]) -> int:
        return len(json.dumps(docs_list, ensure_ascii=False).encode("utf-8"))

    # First, try to apply the max_document_bytes cap
    res_initial = apply_limit(max_document_bytes)
    if get_serialized_size(res_initial) <= max_total_bytes:
        return res_initial

    # If the initial list exceeds max_total_bytes, we need to find a smaller limit L
    # using binary search.
    low = 0
    high = max_document_bytes
    best_res = None

    while low <= high:
        mid = (low + high) // 2
        res_mid = apply_limit(mid)
        size_mid = get_serialized_size(res_mid)

        if size_mid <= max_total_bytes:
            best_res = res_mid
            low = mid + 1  # Try to find a larger limit
        else:
            high = mid - 1 # Try a smaller limit

    if best_res is not None:
        return best_res

    # Fallback in case no limit worked (e.g. max_total_bytes is extremely small),
    # return the list with L=0 limit.
    return apply_limit(0)
